// Generated by Claude - Opus 5.5
// Writes sounds/*.wav: the visitors' calls.
// Everything is synthesized here from sine waves and noise: no samples.
// Run again after changing anything:  node tools/make-sounds.mjs
import { mkdirSync, writeFileSync } from 'node:fs'

const SR = 16000 // samples per second: enough for soft sounds, and keeps each clip small
const OUT = new URL('../sounds/', import.meta.url)
mkdirSync(OUT, { recursive: true })

const TAU = 2 * Math.PI

// --- A sound buffer.
const buffer = seconds => ({ data: new Float32Array(Math.round(seconds * SR)) })

// Add a voice: fn(t) gives the sample t seconds after it starts.
function add(buf, start, seconds, fn) {
  const s0 = Math.round(start * SR)
  for (let i = 0; i < seconds * SR; i++) {
    if (s0 + i >= buf.data.length) break
    buf.data[s0 + i] += fn(i / SR)
  }
}

// --- Building blocks
// A pitch that slides from f0 to f1 (phase is summed so the slide is smooth).
const slide = (f0, f1, len, shape = t => t) => {
  let phase = 0, last = 0
  return t => {
    const f = f0 + (f1 - f0) * shape(Math.min(1, t / len))
    phase += TAU * f * (t - last); last = t
    return Math.sin(phase)
  }
}
// A short sliding note that swells in and out: built once per note, so the slide stays smooth.
const chirp = (f0, f1, len, amp, shape) => { const s = slide(f0, f1, len, shape); return t => s(t) * Math.sin(Math.PI * t / len) * amp }
// Noise from a fixed seed, so rebuilding gives the same files (no needless git changes).
let seed = 1
const noise = () => ((seed = (seed * 1103515245 + 12345) % 2147483648) / 1073741824) - 1

// Cheap underwater room: a few feedback echoes.
function reverb(buf, wet = 0.25) {
  const dry = Float32Array.from(buf.data)
  const out = new Float32Array(dry.length)
  for (const [delay, fb] of [[0.113, 0.55], [0.157, 0.5], [0.211, 0.45], [0.293, 0.4]]) {
    const d = Math.round(delay * SR), y = new Float32Array(dry.length)
    for (let i = 0; i < y.length; i++) y[i] = dry[i] + fb * (i >= d ? y[i - d] : 0)
    for (let i = 0; i < out.length; i++) out[i] += y[i] * wet / 4
  }
  for (let i = 0; i < out.length; i++) buf.data[i] = dry[i] + out[i]
}

// Save as 16-bit mono WAV, scaled so the loudest moment sits at 90%
//.
function save(name, buf, peak = buf.data.reduce((m, v) => Math.max(m, Math.abs(v)), 1e-9)) {
  const bytes = Buffer.alloc(44 + buf.data.length * 2)
  bytes.write('RIFF', 0); bytes.writeUInt32LE(36 + buf.data.length * 2, 4); bytes.write('WAVEfmt ', 8)
  bytes.writeUInt32LE(16, 16); bytes.writeUInt16LE(1, 20); bytes.writeUInt16LE(1, 22)
  bytes.writeUInt32LE(SR, 24); bytes.writeUInt32LE(SR * 2, 28); bytes.writeUInt16LE(2, 32); bytes.writeUInt16LE(16, 34)
  bytes.write('data', 36); bytes.writeUInt32LE(buf.data.length * 2, 40)
  buf.data.forEach((v, i) => bytes.writeInt16LE(Math.round((v / peak) * 0.9 * 32767), 44 + i * 2))
  writeFileSync(new URL(name, OUT), bytes)
  console.log(`${name}: ${(buf.data.length / SR).toFixed(1)} s`)
}

// ===================== Animal voices =====================
// Orca: two whistles that rise and fall, with a little vibrato, echoing.
const orca = buffer(3)
{
  let ph = 0, last = 0
  add(orca, 0, 0.8, t => { // rise and fall
    const f = 1150 + 800 * Math.sin(Math.PI * t / 0.8) + 25 * Math.sin(TAU * 6 * t)
    ph += TAU * f * (t - last); last = t
    return (Math.sin(ph) + 0.25 * Math.sin(2 * ph)) * Math.sin(Math.PI * t / 0.8) * 0.5
  })
  add(orca, 1.0, 0.7, chirp(1900, 1050, 0.7, 0.5, t => t * t))
  add(orca, 1.85, 0.35, chirp(1400, 2100, 0.35, 0.35))
}
reverb(orca, 0.5)
save('orca.wav', orca)

// Sea turtle: slow, low bubbly breaths.
const turtle = buffer(1.4)
for (const at of [0, 0.3, 0.65]) add(turtle, at, 0.18, chirp(240, 130, 0.18, 0.7))
add(turtle, 0, 1.2, t => noise() * 0.05 * Math.sin(Math.PI * t / 1.2))
reverb(turtle, 0.3)
save('turtle.wav', turtle)

// Manta ray: a soft whoosh of water as it glides past.
const manta = buffer(2.6)
{
  let lp = 0
  add(manta, 0, 2.5, t => {
    const cutoff = 0.02 + 0.08 * Math.sin(Math.PI * t / 2.5) // a one-pole filter that opens and closes
    lp += cutoff * (noise() - lp)
    return lp * 3 * Math.sin(Math.PI * t / 2.5)
  })
}
save('manta.wav', manta)

// Seahorse: tiny clicks and a chirp.
const seahorse = buffer(1)
for (const at of [0, 0.12, 0.24]) add(seahorse, at, 0.008, () => noise() * 0.8)
add(seahorse, 0.4, 0.15, chirp(1300, 1700, 0.15, 0.5))
reverb(seahorse, 0.2)
save('seahorse.wav', seahorse)
